message.content:
{
  "title": "The Mirror Rescue of Ruined Rylanth",
  "gate_token": "QxhQWY-Wih5--cH6_M6FrA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver peers into a cracked window.",
      "visual_description": "A ruined street littered with broken glass and fallen royal banners. A figure in a clear diving helmet and a coat reflecting broken city lights stares into a shattered window.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unrolls a map of the city.",
      "visual_description": "Mara crouches behind a collapsed stall, ink-stained coat flapping, brass compass in hand, tracing a route on a frayed map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning from a windowsill.",
      "visual_description": "An oil lamp with one glowing eye in its flame sits on a cracked stone windowsill, casting long shadows across the street.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector dozes on a ledger pillow.",
      "visual_description": "Inside a roofless guardhouse, a figure sleeps on a stack of ledgers, stamped papers stuck to his sleeves, oblivious to the noise outside.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scouts ahead through a broken gate.",
      "visual_description": "A small metal fox with a key-wind tail and blue glass eyes slips through a gap in the rusted castle gates, its ears twitching.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a mirror into a cursed tower.",
      "visual_description": "Inside a crumbling tower room, a tall mirror ripples like water. The glass diver steps through it, diving helmet gleaming.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara consults the map while the Oracle Lamp glows beside her.",
      "visual_description": "Mara and the Oracle Lamp huddle under an archway, the lamp's flame eye casting light on the map's faded ink.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox reports back with a clatter of gears.",
      "visual_description": "The Tin Fox skids to a stop in front of Mara, its clockwork tail ticking, blue eyes blinking twice.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector stirs as a patrol clanks past.",
      "visual_description": "Armored boots stomp past the guardhouse, and the Sleeping Tax Collector shifts, a stamped paper fluttering to the floor.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver finds a magic door inside the tower.",
      "visual_description": "At the top of a spiral stair, a door made of interlocking metal rings hums with faint light. The glass diver reaches out a gloved hand.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Mara and the Tin Fox cross a courtyard under torn banners.",
      "visual_description": "Old royal banners flap in the wind above a cobblestone courtyard. Mara and the Tin Fox dash between collapsed pillars.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp warns of a trap on the path ahead.",
      "visual_description": "The Oracle Lamp's flame eye narrows as it illuminates a tripwire strung across a dark alley. Its glow pulses red.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector snores loudly next to a pile of stamped papers.",
      "visual_description": "The guardhouse floor is covered in stamped documents. The Sleeping Tax Collector snores, one hand clutching a quill.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver opens the magic door and steps through.",
      "visual_description": "The metal-ring door swings open, revealing a corridor of mirrors. The glass diver steps through, reflections multiplying endlessly.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara spots the glass diver's signal from a tower window.",
      "visual_description": "A flash of light from a high tower window catches Mara's eye. She points, and the Tin Fox nods its metal head.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver emerges onto a bridge with a rescued captive.",
      "visual_description": "The glass diver leads a shackled figure (the rescued) onto a stone bridge spanning a dark chasm. The diver's coat reflects the setting sun.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "Mara, the Tin Fox, and the Oracle Lamp rush onto the bridge.",
      "visual_description": "Mara runs onto the bridge, the Tin Fox at her heels, the Oracle Lamp floating beside her, its flame bright with urgency.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The Sleeping Tax Collector wakes up as the bridge collapses behind them.",
      "visual_description": "The Sleeping Tax Collector blinks awake, sees the distant bridge crumble, then yawns and goes back to sleep on the ledgers.",
      "characters": ["sleeping_tax_collector"]
    }
  ]
}

